pV(a,b){return"\u09b8\u09cd\u099f\u09cd\u09b0\u09bf\u0995 \u09ab\u09cd\u09b0\u09bf\u099c: "+b+"\u099f\u09bf\u09b0 \u09ae\u09a7\u09cd\u09af\u09c7 "+a+"\u099f\u09bf"},
pW(a){return"\u09b8\u09cd\u099f\u09cd\u09b0\u09bf\u0995 \u09ac\u09be\u09a1\u09bc\u09be\u09a4\u09c7 \u09aa\u09cd\u09b0\u09a4\u09bf\u09a6\u09bf\u09a8 \u0985\u09a8\u09cd\u09a4\u09a4 \u098f\u0995\u099f\u09be \u0997\u09c7\u09ae \u0996\u09c7\u09b2\u09cb\u0964 \u09b0\u09a4\u09cd\u09a8 \u09a6\u09bf\u09af\u09bc\u09c7 \u0995\u09c7\u09a8\u09be \u098f\u0995\u099f\u09be \u09b8\u09cd\u099f\u09cd\u09b0\u09bf\u0995 \u09ab\u09cd\u09b0\u09bf\u099c \u098f\u0995\u09a6\u09bf\u09a8 \u09ac\u09be\u09a6 \u09aa\u09a1\u09bc\u09b2\u09c7\u0993 \u09b8\u09cd\u099f\u09cd\u09b0\u09bf\u0995 \u09ac\u09be\u0981\u099a\u09bf\u09af\u09bc\u09c7 \u09b0\u09be\u0996\u09c7: \u098f\u099f\u09be \u09a8\u09bf\u099c\u09c7 \u09a5\u09c7\u0995\u09c7\u0987 \u09ac\u09cd\u09af\u09ac\u09b9\u09be\u09b0 \u09b9\u09af\u09bc\u0964 \u09a4\u09c1\u09ae\u09bf "+a+"\u099f\u09bf \u09b0\u09be\u0996\u09a4\u09c7 \u09aa\u09be\u09b0\u09cb\u0964"},
