gDr(){return"\u09ac\u09be\u09a6 \u09a6\u09be\u0993"},
gDp(){return"\u09aa\u09b0\u09c7"},
gDk(){return"\u0985\u09cd\u09af\u09be\u09b0\u09c7\u09a8\u09be\u09af\u09bc \u09b8\u09cd\u09ac\u09be\u0997\u09a4\u09ae"},
gDj(){return"\u09ae\u09a8\u09c7 \u09ae\u09a8\u09c7 \u0985\u0999\u09cd\u0995\u09c7\u09b0 \u09a1\u09c1\u09af\u09bc\u09c7\u09b2\u0964 \u098f\u0995\u099f\u09be \u09aa\u09cd\u09b0\u09b6\u09cd\u09a8, \u0995\u09af\u09bc\u09c7\u0995\u099f\u09be \u0989\u09a4\u09cd\u09a4\u09b0: \u09b8\u09a0\u09bf\u0995\u099f\u09be\u09af\u09bc \u099a\u09be\u09aa\u09cb, \u09af\u09a4 \u09a4\u09be\u09a1\u09bc\u09be\u09a4\u09be\u09a1\u09bc\u09bf \u09aa\u09be\u09b0\u09cb\u0964"},
gDm(){return"\u09a4\u09cb\u09ae\u09be\u09b0 \u0995\u09ae\u09cd\u09ac\u09cb \u0997\u09a1\u09bc\u09cb"},
gDl(){return"\u09aa\u09b0\u09aa\u09b0 \u09aa\u09cd\u09b0\u09a4\u09bf\u099f\u09bf \u09b8\u09a0\u09bf\u0995 \u0989\u09a4\u09cd\u09a4\u09b0 \u09a4\u09cb\u09ae\u09be\u09b0 \u0995\u09ae\u09cd\u09ac\u09cb \u0986\u09b0 \u09aa\u09af\u09bc\u09c7\u09a8\u09cd\u099f \u09ac\u09be\u09a1\u09bc\u09be\u09af\u09bc\u0964 \u098f\u0995\u099f\u09be \u09ad\u09c1\u09b2\u09c7 \u09b8\u09c7\u099f\u09be \u0986\u09ac\u09be\u09b0 \u09b6\u09c2\u09a8\u09cd\u09af \u09b9\u09af\u09bc\u0964 \u09aa\u09cd\u09b0\u09a4\u09bf \u0997\u09c7\u09ae\u09c7\u09b0 \u09aa\u09b0\u09c7 \u09a4\u09cb\u09ae\u09be\u09b0 \u09ad\u09c1\u09b2\u0997\u09c1\u09b2\u09cb \u09a6\u09c7\u0996\u09c7 \u09ac\u09cb\u099d\u09cb \u0995\u09c7\u09a8\u0964"},
gDo(){return"\u09a4\u09cb\u09ae\u09be\u09b0 \u09af\u09be\u09a4\u09cd\u09b0\u09be"},
