gzz(){return"\u0417\u0430\u0431\u0443\u0432 \u043f\u043e\u0434\u0456\u043b\u0438\u0442\u0438 \u043d\u0430\u0432\u043f\u0456\u043b"},
gAe(){return"\u041f\u043b\u043e\u0449\u0430 \u043f\u043e\u0432\u0435\u0440\u0445\u043d\u0456 \u0437\u0430\u043c\u0456\u0441\u0442\u044c \u043e\u0431'\u0454\u043c\u0443"},
gyk(){return"\u0426\u0435 \u0447\u0438\u0441\u043b\u043e \u0434\u0456\u043b\u0438\u0442\u044c \u043e\u0431\u0438\u0434\u0432\u0430 \u0447\u0438\u0441\u043b\u0430, \u0430\u043b\u0435 \u0454 \u0439 \u0431\u0456\u043b\u044c\u0448\u0435: \u0448\u0443\u043a\u0430\u0439 \u043d\u0430\u0439\u0431\u0456\u043b\u044c\u0448\u0435."},
