gyb(){return"\u041d\u0421\u0414 \u043d\u0435 \u0431\u0456\u043b\u044c\u0448\u0438\u0439 \u0437\u0430 \u043c\u0435\u043d\u0448\u0435 \u0447\u0438\u0441\u043b\u043e; \u041d\u0421\u041a \u043d\u0435 \u043c\u0435\u043d\u0448\u0435 \u0437\u0430 \u0431\u0456\u043b\u044c\u0448\u0435."},
gyD(){return"\u0414\u043e\u0431\u0443\u0442\u043e\u043a \u0434\u0432\u043e\u0445 \u0447\u0438\u0441\u0435\u043b \u2014 \u0441\u043f\u0456\u043b\u044c\u043d\u0435 \u043a\u0440\u0430\u0442\u043d\u0435, \u0430\u043b\u0435 \u043d\u0435 \u0437\u0430\u0432\u0436\u0434\u0438 \u043d\u0430\u0439\u043c\u0435\u043d\u0448\u0435: \u043f\u043e\u0434\u0456\u043b\u0438 \u0439\u043e\u0433\u043e \u043d\u0430 \u0457\u0445\u043d\u0456\u0439 \u041d\u0421\u0414."},
gyE(){return"\u0426\u0435 \u0441\u043a\u0456\u043b\u044c\u043a\u0438 \u0440\u0430\u0437\u0456\u0432 \u0447\u0438\u0441\u043b\u043e \u0432\u043c\u0456\u0449\u0443\u0454\u0442\u044c\u0441\u044f; \u043e\u0441\u0442\u0430\u0447\u0430 \u2014 \u0446\u0435 \u0442\u0435, \u0449\u043e \u0437\u0430\u043b\u0438\u0448\u0430\u0454\u0442\u044c\u0441\u044f \u043f\u0456\u0441\u043b\u044f \u0446\u044c\u043e\u0433\u043e."},
gym(){return"\u0426\u0435 \u0447\u0438\u0441\u043b\u043e \u0434\u0456\u043b\u0438\u0442\u044c\u0441\u044f \u043d\u0435 \u043b\u0438\u0448\u0435 \u043d\u0430 1 \u0456 \u043d\u0430 \u0441\u0435\u0431\u0435: \u043f\u0435\u0440\u0435\u0432\u0456\u0440 \u043f\u0440\u043e\u0441\u0442\u0456 \u0447\u0438\u0441\u043b\u0430 \u0434\u043e \u0439\u043e\u0433\u043e \u043a\u0432\u0430\u0434\u0440\u0430\u0442\u043d\u043e\u0433\u043e \u043a\u043e\u0440\u0435\u043d\u044f (2, 3, 5, 7, 11, 13, 17\u2026)."},
gyj(){return"\u0412\u0438\u043a\u043e\u0440\u0438\u0441\u0442\u043e\u0432\u0443\u0439 \u043e\u0437\u043d\u0430\u043a\u0438: \u0434\u043b\u044f 3 \u0430\u0431\u043e 9 \u0434\u043e\u0434\u0430\u0439 \u0446\u0438\u0444\u0440\u0438; \u0434\u043b\u044f 4 \u0434\u0438\u0432\u0438\u0441\u044c \u043d\u0430 \u0434\u0432\u0456 \u043e\u0441\u0442\u0430\u043d\u043d\u0456 \u0446\u0438\u0444\u0440\u0438; \u0434\u043b\u044f 6 \u2014 \u043f\u0430\u0440\u043d\u0435 \u0439 \u0434\u0456\u043b\u0438\u0442\u044c\u0441\u044f \u043d\u0430 3."},
gxU(){return"\u0427\u0438\u0441\u043b\u043e \u043f\u0435\u0440\u0435\u0434 \u0434\u0443\u0436\u043a\u0430\u043c\u0438 \u043c\u043d\u043e\u0436\u0438\u0442\u044c\u0441\u044f \u043d\u0430 \u0432\u0441\u0435 \u0432\u0441\u0435\u0440\u0435\u0434\u0438\u043d\u0456: 3(x + 2) \u2014 \u0446\u0435 3x + 6, \u0430 \u043d\u0435 3x + 2."},
gyw(){return"\u041f\u043b\u043e\u0449\u0430 \u2014 \u0446\u0435 \u043f\u043e\u0432\u0435\u0440\u0445\u043d\u044f: \u0434\u043e\u0432\u0436\u0438\u043d\u0430 \xd7 \u0448\u0438\u0440\u0438\u043d\u0430. \u0421\u0443\u043c\u0430 \u0441\u0442\u043e\u0440\u0456\u043d \u2014 \u0446\u0435 \u043f\u0435\u0440\u0438\u043c\u0435\u0442\u0440."},
gyR(){return"\u0421\u0443\u043c\u0430 \u043a\u0443\u0442\u0456\u0432 \u0442\u0440\u0438\u043a\u0443\u0442\u043d\u0438\u043a\u0430 180\xb0, \u043f\u0440\u044f\u043c\u0430 \u043b\u0456\u043d\u0456\u044f \u2014 180\xb0, \u0430 \u0441\u0443\u043c\u0430 \u043a\u0443\u0442\u0456\u0432 \u0447\u043e\u0442\u0438\u0440\u0438\u043a\u0443\u0442\u043d\u0438\u043a\u0430 360\xb0."},
gyM(){return"\u0417\u0430 \u041f\u0456\u0444\u0430\u0433\u043e\u0440\u043e\u043c: \u043f\u0456\u0434\u043d\u0435\u0441\u0438 \u043e\u0431\u0438\u0434\u0432\u0456 \u0441\u0442\u043e\u0440\u043e\u043d\u0438 \u0434\u043e \u043a\u0432\u0430\u0434\u0440\u0430\u0442\u0430, \u0434\u043e\u0434\u0430\u0439 \u043a\u0432\u0430\u0434\u0440\u0430\u0442\u0438, \u043f\u043e\u0442\u0456\u043c \u0434\u043e\u0431\u0443\u0434\u044c \u043a\u0432\u0430\u0434\u0440\u0430\u0442\u043d\u0438\u0439 \u043a\u043e\u0440\u0456\u043d\u044c."},
gy3(){return"\u0411\u0440\u0430\u043a\u0443\u0454 \u043a\u0432\u0430\u0434\u0440\u0430\u0442\u043d\u043e\u0433\u043e \u043a\u043e\u0440\u0435\u043d\u044f: \u0437\u043d\u0430\u0439\u0434\u0438 \u0447\u0438\u0441\u043b\u043e, \u044f\u043a\u0435 \u043f\u0440\u0438 \u043c\u043d\u043e\u0436\u0435\u043d\u043d\u0456 \u043d\u0430 \u0441\u0435\u0431\u0435 \u0434\u0430\u0454 \u0446\u0435\u0439 \u0440\u0435\u0437\u0443\u043b\u044c\u0442\u0430\u0442 (\u0437\u0430 \u041f\u0456\u0444\u0430\u0433\u043e\u0440\u043e\u043c a\xb2 + b\xb2 \u2014 \u0446\u0435 \u043a\u0432\u0430\u0434\u0440\u0430\u0442 \u043d\u0430\u0439\u0434\u043e\u0432\u0448\u043e\u0457 \u0441\u0442\u043e\u0440\u043e\u043d\u0438)."},
gy0(){return"\u0422\u0440\u0438\u043a\u0443\u0442\u043d\u0438\u043a \u2014 \u0446\u0435 \u043f\u043e\u043b\u043e\u0432\u0438\u043d\u0430 \u043f\u0440\u044f\u043c\u043e\u043a\u0443\u0442\u043d\u0438\u043a\u0430: \u043e\u0441\u043d\u043e\u0432\u0430 \xd7 \u0432\u0438\u0441\u043e\u0442\u0430 \xf7 2."},
