gnG(){return"\u0422\u0435\u0441\u0442\u043e\u0432\u0430 \u0432\u0435\u0440\u0441\u0456\u044f"},
gnH(){return"\u0412\u0456\u0434\u043a\u0440\u0438\u0442\u0438 \u0432\u0441\u0435"},
